#### 1. Add Stripe Elements to the form (client)

```tsx
// components/Checkout.tsx
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { useState } from 'react';

const stripePromise = loadStripe('pk_test_XXXXXXXXXXXXXXXXXXXX'); // publishable key – keep it public

export function Checkout() {
  const stripe = useStripe();
  const elements = useElements();
  const [error, setError] = useState(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!stripe || !elements) return;

    // 1️⃣ Create a PaymentMethod on Stripe
    const { error: stripeErr, paymentMethod } = await stripe.createPaymentMethod({
      type: 'card',
      card: elements.getElement(CardElement) as any,
    });

    if (stripeErr) {
      setError(stripeErr.message);
      return;
    }

    // 2️⃣ Send the ID to our backend to store it
    const res = await fetch('/api/store-payment-method', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({paymentMethodId: paymentMethod.id}),
    });

    const data = await res.json();
    if (!res.ok) {
      setError(data.message || 'Unknown error');
      return;
    }

    // 3️⃣ Now we can create a PaymentIntent on the backend later
    alert('Payment method saved! You can use it on future purchases.');
  };

  return (
    <Elements stripe={stripePromise}>
      <form onSubmit={handleSubmit}>
        <CardElement />
        <button type="submit" disabled={!stripe}>Save my card</button>
      </form>
      {error && <p style={{color:"red"}}>{error}</p>}
    </Elements>
  );
}
```

> *What it does:*  
> 1. Uses Stripe Elements to collect card details **without revealing the card number to our server**.  
> 2. Calls `stripe.createPaymentMethod`, giving us a secure `paymentMethod.id`.  
> 3. Sends that ID (not the card) to a protected API route on your server where we’ll attach it to the user.

